-- ── story 5-6a: credit and debit notes against a client services invoice ──
-- Generated by drizzle-kit (the four tables and their indexes) and
-- hand-amended around the generated part: the fail-fast guard, `IF NOT
-- EXISTS` on every table and index (guide §3), the CHECKs, the freeze / cap /
-- maker-checker triggers, the invoice-void guard, the RLS policies and the
-- post-migration probe (drizzle-kit is blind to CHECKs, triggers and RLS;
-- `bun run db:generate` afterwards reports "No schema changes").
--
--   client_invoice_notes        — a GST note (CGST Act s.34) of kind credit |
--                                 debit against exactly ONE issued, disputed
--                                 or settled client invoice: draft → issued
--                                 (numbered, frozen) → void. Copies the
--                                 invoice's GSTIN, place of supply, supply
--                                 type and frozen party (the INSERT arm
--                                 checks them). Amounts are positive
--                                 magnitudes; the kind gives the sign.
--   client_invoice_note_lines   — one per referenced invoice line, the
--                                 taxable delta and its three heads; copies
--                                 the invoice line's nine descriptive and tax
--                                 columns (the lines trigger checks them).
--   client_invoice_note_series  — the C and D series per (tenant, supplying
--                                 GSTIN, kind, FY of the note's issue).
--   client_invoice_note_policies — the tenant's credit-note maker/checker
--                                 switch (a missing row = REQUIRED).
--
-- client_invoices gains ONE trigger (`client_invoices_void_needs_no_notes`);
-- 0062's `client_invoices_guard()` keeps its bytes.
--
-- No data: purely additive. Lock cost: four new empty tables; the one new
-- trigger on `client_invoices` is metadata (CREATE TRIGGER takes SHARE ROW
-- EXCLUSIVE briefly, no scan). The deploy migrator's `lock_timeout` applies
-- (DEPLOY.md §5). Proven by the migration block in
-- `test/client-invoice-notes.spec.ts` (applied to a database built from the
-- journal trimmed before it, inside one transaction).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'client_invoice_notes'
	) THEN
		RAISE EXCEPTION 'migration 0098: client_invoice_notes already exists — this migration has already been applied.';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'client_invoices'
	) THEN
		RAISE EXCEPTION 'migration 0098 is out of order: client_invoices does not exist — 0062 must be applied first.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "client_invoice_note_lines" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"note_id" uuid NOT NULL,
	"invoice_line_id" uuid NOT NULL,
	"charge_code" text NOT NULL,
	"basis" text NOT NULL,
	"uom" text,
	"segment_from" timestamp with time zone NOT NULL,
	"segment_to" timestamp with time zone NOT NULL,
	"sac_code" text NOT NULL,
	"gst_bps" integer NOT NULL,
	"place_of_supply" text NOT NULL,
	"supply_type" text NOT NULL,
	"amount_paise" bigint NOT NULL,
	"cgst_paise" bigint NOT NULL,
	"sgst_paise" bigint NOT NULL,
	"igst_paise" bigint NOT NULL,
	"override_reason" text,
	-- ── hand-amended: the line CHECKs (migration SQL only) ────────────────
	-- The pair implies the vocabularies (CHARGE_CODES / RATE_BASES /
	-- CHARGE_BASIS in rate-cards.ts — the 0062 pair, one constraint here).
	CONSTRAINT "client_invoice_note_lines_charge_basis" CHECK (
		("charge_code" = 'storage' AND "basis" = 'per_thousand_units_per_day')
		OR ("charge_code" = 'inbound_handling' AND "basis" = 'per_receipt_line')
		OR ("charge_code" = 'pick' AND "basis" = 'per_pick')
		OR ("charge_code" = 'outbound_handling' AND "basis" = 'per_order')
	),
	CONSTRAINT "client_invoice_note_lines_uom_basis" CHECK (
		("basis" = 'per_thousand_units_per_day') = ("uom" IS NOT NULL)
	),
	-- The taxable delta: always positive (a magnitude; the kind is the sign).
	CONSTRAINT "client_invoice_note_lines_amount" CHECK ("amount_paise" > 0),
	-- SAC, rate, place of supply and the head split by supply type (0062's
	-- lines_tax, the non-null arms only: a note's line always has a supply type).
	CONSTRAINT "client_invoice_note_lines_tax" CHECK (
		"sac_code" ~ '^[0-9]{6}$'
		AND "gst_bps" BETWEEN 0 AND 10000
		AND "place_of_supply" ~ '^[0-9]{2}$'
		AND "cgst_paise" >= 0 AND "sgst_paise" >= 0 AND "igst_paise" >= 0
		AND (
			("supply_type" = 'intra' AND "igst_paise" = 0)
			OR ("supply_type" = 'inter' AND "cgst_paise" = 0 AND "sgst_paise" = 0)
		)
	),
	CONSTRAINT "client_invoice_note_lines_override_reason" CHECK (
		"override_reason" IS NULL
		OR (char_length(btrim("override_reason")) BETWEEN 1 AND 500 AND "override_reason" = btrim("override_reason"))
	)
);
