CREATE TABLE IF NOT EXISTS "client_invoice_notes" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid NOT NULL,
	"invoice_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"supplier_gstin" text NOT NULL,
	"place_of_supply" text NOT NULL,
	"supply_type" text NOT NULL,
	"reason" text NOT NULL,
	"reason_note" text NOT NULL,
	"settles_dispute" boolean DEFAULT false NOT NULL,
	"note_no" text,
	"fy_label" text,
	"series_seq" integer,
	"subtotal_paise" bigint NOT NULL,
	"cgst_paise" bigint NOT NULL,
	"sgst_paise" bigint NOT NULL,
	"igst_paise" bigint NOT NULL,
	"tax_paise" bigint NOT NULL,
	"total_paise" bigint NOT NULL,
	"round_off_paise" bigint NOT NULL,
	"payable_paise" bigint NOT NULL,
	"party" jsonb NOT NULL,
	"issued_at" timestamp with time zone,
	"issued_by" uuid,
	"void_note" text,
	"voided_at" timestamp with time zone,
	"voided_by" uuid,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	-- ── hand-amended: the note CHECKs (migration SQL only) ────────────────
	-- Mirrored by NOTE_KINDS / NOTE_STATUSES / NOTE_REASONS_BY_KIND
	-- (billing/client-invoice-notes.ts), pinned by test/client-invoice-notes.spec.ts.
	CONSTRAINT "client_invoice_notes_kind" CHECK ("kind" IN ('credit', 'debit')),
	CONSTRAINT "client_invoice_notes_status" CHECK ("status" IN ('draft', 'issued', 'void')),
	-- The reason vocabulary is paired with the kind (A2).
	CONSTRAINT "client_invoice_notes_reason" CHECK (
		("kind" = 'credit' AND "reason" IN ('deficiency-in-service', 'post-supply-discount', 'excess-billed'))
		OR ("kind" = 'debit' AND "reason" = 'short-billed')
	),
	-- Only a credit settles a dispute (A2).
	CONSTRAINT "client_invoice_notes_settles" CHECK (NOT "settles_dispute" OR "kind" = 'credit'),
	CONSTRAINT "client_invoice_notes_reason_note" CHECK (
		char_length(btrim("reason_note")) BETWEEN 1 AND 500 AND "reason_note" = btrim("reason_note")
	),
	CONSTRAINT "client_invoice_notes_tax_shape" CHECK (
		"supplier_gstin" ~ '^[0-9]{2}[A-Z0-9]{13}$'
		AND "place_of_supply" ~ '^[0-9]{2}$'
		AND "supply_type" IN ('intra', 'inter')
	),
	-- A8: exact sums, and NO rupee rounding of its own — the round-off is
	-- non-zero only on a credit (the one that exhausts the invoice, or one
	-- clamped to the payable that remains), within −49…+50; no `% 100`.
	CONSTRAINT "client_invoice_notes_totals" CHECK (
		"subtotal_paise" >= 0 AND "cgst_paise" >= 0 AND "sgst_paise" >= 0 AND "igst_paise" >= 0
		AND "subtotal_paise" + "tax_paise" = "total_paise"
		AND "cgst_paise" + "sgst_paise" + "igst_paise" = "tax_paise"
		AND "payable_paise" = "total_paise" + "round_off_paise"
		AND "round_off_paise" BETWEEN -49 AND 50
		AND "payable_paise" >= 0
		AND ("kind" = 'credit' OR "round_off_paise" = 0)
	),
	-- draft ⇔ no number ⇔ never issued; a number carries its FY, sequence and
	-- stamps; its series letter is the kind's (C / D).
	CONSTRAINT "client_invoice_notes_numbered" CHECK (
		("status" = 'draft') = ("note_no" IS NULL)
		AND ("note_no" IS NULL) = ("fy_label" IS NULL)
		AND ("note_no" IS NULL) = ("series_seq" IS NULL)
		AND ("note_no" IS NULL) = ("issued_at" IS NULL)
		AND ("issued_at" IS NULL) = ("issued_by" IS NULL)
		AND ("fy_label" IS NULL OR "fy_label" ~ '^FY-[0-9]{4}$')
		AND ("note_no" IS NULL OR "note_no" ~ '^[0-9]{2}/[CD][0-9]{4}/[0-9]{6}$')
		AND ("note_no" IS NULL OR substr("note_no", 4, 1) = CASE "kind" WHEN 'credit' THEN 'C' ELSE 'D' END)
	),
	-- void ⇔ the void stamps and its note (1–500, trimmed).
	CONSTRAINT "client_invoice_notes_void" CHECK (
		("status" = 'void') = ("voided_at" IS NOT NULL)
		AND ("voided_at" IS NULL) = ("voided_by" IS NULL)
		AND ("voided_at" IS NULL) = ("void_note" IS NULL)
		AND ("void_note" IS NULL OR (char_length(btrim("void_note")) BETWEEN 1 AND 500 AND "void_note" = btrim("void_note")))
	),
	CONSTRAINT "client_invoice_notes_party" CHECK (jsonb_typeof("party") = 'object' AND "party" <> '{}'::jsonb)
);
