-- ── the notes guard (A19, A20, A7) ───────────────────────────────────────
-- INSERT: only a draft, and only against an invoice it may amend — read
-- FOR SHARE (missing or invisible = refused: fail closed), with the same
-- tenant, client, supplying GSTIN, place of supply, supply type and party.
-- A credit amends an issued | disputed | settled invoice, a debit only an
-- issued one; a settling credit needs a disputed one.
-- UPDATE: the identity never changes. draft → draft passes. draft → issued
-- needs the stamps, at least one line, the header equal to the lines' sums
-- and every figure as it was; it takes the invoice row FOR UPDATE (the
-- command already holds it; a writer that bypasses the command is then
-- serialised too), re-checks eligibility, and for a CREDIT: maker/checker
-- under the tenant's policy (a missing row = required), and the cap — per
-- invoice line, Σ taxable and each Σ head over the ISSUED credits PLUS this
-- note's own lines (it is still a draft in BEFORE UPDATE) ≤ the invoice
-- line's, and Σ issued credit payable plus this note's ≤ the invoice
-- payable. issued → void needs the void stamps (and a second person for a
-- credit), and never voids a credit that settled a dispute (A5). Every other move — void → anything included — is refused.
-- DELETE: only a draft with no lines.
-- VOLATILE: under READ COMMITTED each statement takes a fresh snapshot, so
-- the sums after the lock see a competitor that just committed. TIME is not
-- checked here — the command's clock owns the deadlines.
CREATE FUNCTION "client_invoice_notes_guard"() RETURNS trigger LANGUAGE plpgsql VOLATILE AS $$
DECLARE
	inv record;
	needs_second boolean;
	line_count bigint;
	sum_amount bigint;
	sum_cgst bigint;
	sum_sgst bigint;
	sum_igst bigint;
	over_line uuid;
	prior_payable bigint;
	issue_cols text[] := ARRAY['status', 'note_no', 'fy_label', 'series_seq', 'issued_at', 'issued_by', 'updated_at'];
	void_cols text[] := ARRAY['status', 'void_note', 'voided_at', 'voided_by', 'updated_at'];
BEGIN
	IF TG_OP = 'DELETE' THEN
		IF OLD."status" <> 'draft' THEN
			RAISE EXCEPTION 'client_invoice_notes: a % note is never deleted (note %)', OLD."status", OLD."id";
		END IF;
		IF EXISTS (SELECT 1 FROM "client_invoice_note_lines" WHERE "note_id" = OLD."id") THEN
			RAISE EXCEPTION 'client_invoice_notes: draft % still has lines — delete its lines first', OLD."id";
		END IF;
		RETURN OLD;
	END IF;

	IF TG_OP = 'INSERT' THEN
		IF NEW."status" IS DISTINCT FROM 'draft' THEN
			RAISE EXCEPTION 'client_invoice_notes: a note is born a draft (note %)', NEW."id";
		END IF;
		SELECT "tenant_id", "client_id", "status", "supplier_gstin", "place_of_supply", "supply_type", "party"
			INTO inv FROM "client_invoices" WHERE "id" = NEW."invoice_id" FOR SHARE;
		IF NOT FOUND THEN
			RAISE EXCEPTION 'client_invoice_notes: invoice % is missing — a note amends an existing invoice', NEW."invoice_id";
		END IF;
		IF inv."tenant_id" IS DISTINCT FROM NEW."tenant_id"
			OR inv."client_id" IS DISTINCT FROM NEW."client_id"
			OR inv."supplier_gstin" IS DISTINCT FROM NEW."supplier_gstin"
			OR inv."place_of_supply" IS DISTINCT FROM NEW."place_of_supply"
			OR inv."supply_type" IS DISTINCT FROM NEW."supply_type"
			OR inv."party" IS DISTINCT FROM NEW."party" THEN
			RAISE EXCEPTION 'client_invoice_notes: a note copies its invoice''s tenant, client, GSTIN, place of supply, supply type and party (invoice %)', NEW."invoice_id";
		END IF;
		IF NOT ((NEW."kind" = 'credit' AND inv."status" IN ('issued', 'disputed', 'settled'))
			OR (NEW."kind" = 'debit' AND inv."status" = 'issued')) THEN
			RAISE EXCEPTION 'client_invoice_notes: a % note cannot amend a % invoice (invoice %)', NEW."kind", inv."status", NEW."invoice_id";
		END IF;
		IF NEW."settles_dispute" AND inv."status" <> 'disputed' THEN
			RAISE EXCEPTION 'client_invoice_notes: only a disputed invoice is settled by a note (invoice % is %)', NEW."invoice_id", inv."status";
		END IF;
		RETURN NEW;
	END IF;

	-- UPDATE.
	IF NEW."id" IS DISTINCT FROM OLD."id"
		OR NEW."tenant_id" IS DISTINCT FROM OLD."tenant_id"
		OR NEW."client_id" IS DISTINCT FROM OLD."client_id"
		OR NEW."invoice_id" IS DISTINCT FROM OLD."invoice_id"
		OR NEW."kind" IS DISTINCT FROM OLD."kind"
		OR NEW."supplier_gstin" IS DISTINCT FROM OLD."supplier_gstin"
		OR NEW."place_of_supply" IS DISTINCT FROM OLD."place_of_supply"
		OR NEW."supply_type" IS DISTINCT FROM OLD."supply_type"
		OR NEW."reason" IS DISTINCT FROM OLD."reason"
		OR NEW."reason_note" IS DISTINCT FROM OLD."reason_note"
		OR NEW."settles_dispute" IS DISTINCT FROM OLD."settles_dispute"
		OR NEW."party" IS DISTINCT FROM OLD."party"
		OR NEW."created_by" IS DISTINCT FROM OLD."created_by"
		OR NEW."created_at" IS DISTINCT FROM OLD."created_at" THEN
		RAISE EXCEPTION 'client_invoice_notes: the identity of note % never changes', OLD."id";
	END IF;

	IF OLD."status" = 'draft' AND NEW."status" = 'draft' THEN
		RETURN NEW;
	END IF;

	IF OLD."status" = 'draft' AND NEW."status" = 'issued' THEN
		IF NEW."note_no" IS NULL OR NEW."fy_label" IS NULL OR NEW."series_seq" IS NULL
			OR NEW."issued_at" IS NULL OR NEW."issued_by" IS NULL THEN
			RAISE EXCEPTION 'client_invoice_notes: note % cannot issue without its number, FY, sequence and issue stamps', OLD."id";
		END IF;
		IF (to_jsonb(NEW) - issue_cols) IS DISTINCT FROM (to_jsonb(OLD) - issue_cols) THEN
			RAISE EXCEPTION 'client_invoice_notes: note % issues with the figures it was drafted with — only its number and stamps change', OLD."id";
		END IF;
		SELECT count(*), coalesce(sum("amount_paise"), 0), coalesce(sum("cgst_paise"), 0),
				coalesce(sum("sgst_paise"), 0), coalesce(sum("igst_paise"), 0)
			INTO line_count, sum_amount, sum_cgst, sum_sgst, sum_igst
			FROM "client_invoice_note_lines" WHERE "note_id" = OLD."id";
		IF line_count = 0 THEN
			RAISE EXCEPTION 'client_invoice_notes: note % has no line — it cannot issue', OLD."id";
		END IF;
		IF NEW."subtotal_paise" <> sum_amount OR NEW."cgst_paise" <> sum_cgst
			OR NEW."sgst_paise" <> sum_sgst OR NEW."igst_paise" <> sum_igst THEN
			RAISE EXCEPTION 'client_invoice_notes: note % header totals are not the sums of its lines — it cannot issue', OLD."id";
		END IF;
		SELECT "status", "payable_paise" INTO inv FROM "client_invoices" WHERE "id" = NEW."invoice_id" FOR UPDATE;
		IF NOT FOUND THEN
			RAISE EXCEPTION 'client_invoice_notes: invoice % is missing — note % cannot issue', NEW."invoice_id", OLD."id";
		END IF;
		IF NOT ((NEW."kind" = 'credit' AND inv."status" IN ('issued', 'disputed', 'settled'))
			OR (NEW."kind" = 'debit' AND inv."status" = 'issued')) THEN
			RAISE EXCEPTION 'client_invoice_notes: a % note cannot amend a % invoice (invoice %)', NEW."kind", inv."status", NEW."invoice_id";
		END IF;
		IF NEW."settles_dispute" AND inv."status" <> 'disputed' THEN
			RAISE EXCEPTION 'client_invoice_notes: only a disputed invoice is settled by a note (invoice % is %)', NEW."invoice_id", inv."status";
		END IF;
		IF NEW."kind" = 'credit' THEN
			needs_second := coalesce(
				(SELECT "require_second_approver" FROM "client_invoice_note_policies" WHERE "tenant_id" = NEW."tenant_id"),
				true);
			IF needs_second AND NEW."issued_by" = NEW."created_by" THEN
				RAISE EXCEPTION 'client_invoice_notes: credit note % needs a second approver — its creator cannot issue it', OLD."id";
			END IF;
			SELECT il."id" INTO over_line
				FROM "client_invoice_lines" il
				LEFT JOIN (
					SELECT l."invoice_line_id", sum(l."amount_paise") AS a, sum(l."cgst_paise") AS c,
							sum(l."sgst_paise") AS s, sum(l."igst_paise") AS i
						FROM "client_invoice_note_lines" l
						JOIN "client_invoice_notes" n ON n."id" = l."note_id"
						WHERE n."invoice_id" = NEW."invoice_id" AND n."kind" = 'credit'
							AND (n."status" = 'issued' OR n."id" = NEW."id")
						GROUP BY l."invoice_line_id"
				) cr ON cr."invoice_line_id" = il."id"
				WHERE il."invoice_id" = NEW."invoice_id"
					AND (coalesce(cr.a, 0) > coalesce(il."amount_paise", 0)
						OR coalesce(cr.c, 0) > il."cgst_paise"
						OR coalesce(cr.s, 0) > il."sgst_paise"
						OR coalesce(cr.i, 0) > il."igst_paise")
				LIMIT 1;
			IF over_line IS NOT NULL THEN
				RAISE EXCEPTION 'client_invoice_notes: credit note % exceeds invoice line % — the issued credits would pass its taxable value or a tax head', OLD."id", over_line;
			END IF;
			SELECT coalesce(sum("payable_paise"), 0) INTO prior_payable
				FROM "client_invoice_notes"
				WHERE "invoice_id" = NEW."invoice_id" AND "kind" = 'credit' AND "status" = 'issued' AND "id" <> NEW."id";
			IF prior_payable + NEW."payable_paise" > inv."payable_paise" THEN
				RAISE EXCEPTION 'client_invoice_notes: credit note % exceeds the invoice payable — the issued credits would pass %', OLD."id", inv."payable_paise";
			END IF;
		END IF;
		RETURN NEW;
	END IF;

	IF OLD."status" = 'issued' AND NEW."status" = 'void' THEN
		IF NEW."voided_at" IS NULL OR NEW."voided_by" IS NULL OR NEW."void_note" IS NULL THEN
			RAISE EXCEPTION 'client_invoice_notes: a void carries its note and stamps (note %)', OLD."id";
		END IF;
		IF (to_jsonb(NEW) - void_cols) IS DISTINCT FROM (to_jsonb(OLD) - void_cols) THEN
			RAISE EXCEPTION 'client_invoice_notes: note % is frozen — a void changes only its status, note and stamps', OLD."id";
		END IF;
		-- A5: a settled invoice never reopens, so the credit that settled it is never voided.
		IF OLD."settles_dispute" THEN
			RAISE EXCEPTION 'client_invoice_notes: credit note % settled its invoice''s dispute — it is never voided', OLD."id";
		END IF;
		IF NEW."kind" = 'credit' THEN
			needs_second := coalesce(
				(SELECT "require_second_approver" FROM "client_invoice_note_policies" WHERE "tenant_id" = NEW."tenant_id"),
				true);
			IF needs_second AND NEW."voided_by" = NEW."issued_by" THEN
				RAISE EXCEPTION 'client_invoice_notes: credit note % needs a second approver — its issuer cannot void it', OLD."id";
			END IF;
		END IF;
		RETURN NEW;
	END IF;

	RAISE EXCEPTION 'client_invoice_notes: note % is frozen — % → % is not a transition', OLD."id", OLD."status", NEW."status";
END;
$$;--> statement-breakpoint
CREATE TRIGGER "client_invoice_notes_frozen" BEFORE INSERT OR UPDATE OR DELETE ON "client_invoice_notes"
	FOR EACH ROW EXECUTE FUNCTION "client_invoice_notes_guard"();--> statement-breakpoint
-- Lines change only while their note is a draft — the OLD and the NEW parent,
-- read FOR SHARE (missing or invisible = not a draft: fail closed); a line
-- carries its note's tenant and names a line OF THE NOTE'S INVOICE whose
-- nine copied columns it equals (A11).
CREATE FUNCTION "client_invoice_note_lines_guard"() RETURNS trigger LANGUAGE plpgsql VOLATILE AS $$
DECLARE
	parent_status text;
	parent_tenant uuid;
	parent_invoice uuid;
	src record;
BEGIN
	IF TG_OP IN ('UPDATE', 'DELETE') THEN
		SELECT "status" INTO parent_status FROM "client_invoice_notes" WHERE "id" = OLD."note_id" FOR SHARE;
		IF parent_status IS DISTINCT FROM 'draft' THEN
			RAISE EXCEPTION 'client_invoice_note_lines: note % is not a draft (%) — its lines are frozen', OLD."note_id", coalesce(parent_status, 'missing');
		END IF;
	END IF;
	IF TG_OP IN ('INSERT', 'UPDATE') THEN
		parent_status := NULL;
		SELECT "status", "tenant_id", "invoice_id" INTO parent_status, parent_tenant, parent_invoice
			FROM "client_invoice_notes" WHERE "id" = NEW."note_id" FOR SHARE;
		IF parent_status IS DISTINCT FROM 'draft' THEN
			RAISE EXCEPTION 'client_invoice_note_lines: note % is not a draft (%) — its lines are frozen', NEW."note_id", coalesce(parent_status, 'missing');
		END IF;
		IF NEW."tenant_id" IS DISTINCT FROM parent_tenant THEN
			RAISE EXCEPTION 'client_invoice_note_lines: a line carries its note''s tenant (note %)', NEW."note_id";
		END IF;
		SELECT "charge_code", "basis", "uom", "segment_from", "segment_to", "sac_code", "gst_bps", "place_of_supply", "supply_type"
			INTO src FROM "client_invoice_lines"
			WHERE "id" = NEW."invoice_line_id" AND "invoice_id" = parent_invoice AND "tenant_id" = NEW."tenant_id";
		IF NOT FOUND THEN
			RAISE EXCEPTION 'client_invoice_note_lines: invoice line % is not a line of the note''s invoice %', NEW."invoice_line_id", parent_invoice;
		END IF;
		IF src."charge_code" IS DISTINCT FROM NEW."charge_code"
			OR src."basis" IS DISTINCT FROM NEW."basis"
			OR src."uom" IS DISTINCT FROM NEW."uom"
			OR src."segment_from" IS DISTINCT FROM NEW."segment_from"
			OR src."segment_to" IS DISTINCT FROM NEW."segment_to"
			OR src."sac_code" IS DISTINCT FROM NEW."sac_code"
			OR src."gst_bps" IS DISTINCT FROM NEW."gst_bps"
			OR src."place_of_supply" IS DISTINCT FROM NEW."place_of_supply"
			OR src."supply_type" IS DISTINCT FROM NEW."supply_type" THEN
			RAISE EXCEPTION 'client_invoice_note_lines: a line copies its invoice line''s charge, basis, uom, segment, SAC, rate, place of supply and supply type (invoice line %)', NEW."invoice_line_id";
		END IF;
	END IF;
	IF TG_OP = 'DELETE' THEN
		RETURN OLD;
	END IF;
	RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "client_invoice_note_lines_frozen" BEFORE INSERT OR UPDATE OR DELETE ON "client_invoice_note_lines"
	FOR EACH ROW EXECUTE FUNCTION "client_invoice_note_lines_guard"();--> statement-breakpoint
CREATE FUNCTION "client_invoice_notes_refuse_truncate"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	RAISE EXCEPTION '% is never truncated: an issued credit or debit note is frozen', TG_TABLE_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "client_invoice_notes_no_truncate" BEFORE TRUNCATE ON "client_invoice_notes"
	FOR EACH STATEMENT EXECUTE FUNCTION "client_invoice_notes_refuse_truncate"();--> statement-breakpoint
CREATE TRIGGER "client_invoice_note_lines_no_truncate" BEFORE TRUNCATE ON "client_invoice_note_lines"
	FOR EACH STATEMENT EXECUTE FUNCTION "client_invoice_notes_refuse_truncate"();--> statement-breakpoint
-- A4 — an invoice with an ISSUED note is never voided: void its notes first.
-- A separate trigger, so 0062's `client_invoices_guard()` keeps its bytes.
CREATE FUNCTION "client_invoices_void_guard"() RETURNS trigger LANGUAGE plpgsql VOLATILE AS $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM "client_invoice_notes"
		WHERE "tenant_id" = NEW."tenant_id" AND "invoice_id" = NEW."id" AND "status" = 'issued'
	) THEN
		RAISE EXCEPTION 'client_invoices: invoice % has issued credit or debit notes — void its notes first', NEW."id";
	END IF;
	RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "client_invoices_void_needs_no_notes" BEFORE UPDATE OF "status" ON "client_invoices"
