-- ── the post-migration assertion (the 0064 / 0097 model) ─────────────────
-- What landed: RLS on the four tables, the ten policies, the five triggers,
-- the four uniques (`to_regclass`). Then, on made-up uuids inside one
-- subtransaction rolled back by a sentinel: an issued invoice of one line,
-- and the ACCEPTED shapes through the live triggers — a credit drafted,
-- issued by a second person and voided by a third; a debit with an
-- override line issued by its creator; a credit that exhausts the invoice
-- (round-off +20); a series row of each kind; a policy row. Then the
-- TRIGGER refusals (P0001, each matched on its message): an issue over the
-- cap, an issue by the creator, a mismatched-client insert, an issued
-- insert, void → issued, void → draft, an edit of an issued note, a delete
-- of one, a line on an issued note, a line of another invoice, a line that
-- does not copy its invoice line, an invoice void with an issued note, a
-- TRUNCATE. Last, with the two row triggers DISABLED (inside the same
-- rolled-back subtransaction), every named CHECK and unique refused by its
-- own name.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	c2 uuid := gen_random_uuid();
	u1 uuid := gen_random_uuid();
	u2 uuid := gen_random_uuid();
	u3 uuid := gen_random_uuid();
	inv uuid := gen_random_uuid();
	il uuid := gen_random_uuid();
	n1 uuid := gen_random_uuid();
	n2 uuid := gen_random_uuid();
	nc uuid := gen_random_uuid();
	nx uuid := gen_random_uuid();
	nb uuid := gen_random_uuid();
	ns uuid := gen_random_uuid();
	inv2 uuid := gen_random_uuid();
	il2 uuid := gen_random_uuid();
	lb uuid := gen_random_uuid();
	g text := '29AAACT1234A1Z5';
	pty jsonb := '{"probe": true}'::jsonb;
	seg_from timestamptz := '2026-08-31T18:30:00Z';
	seg_to timestamptz := '2026-09-30T18:30:00Z';
	refused_by text;
	refused_message text;
	expected text;
	probe text;
BEGIN
	IF (SELECT count(*) FROM pg_class
		WHERE relname IN ('client_invoice_notes', 'client_invoice_note_lines', 'client_invoice_note_series', 'client_invoice_note_policies')
			AND relrowsecurity) <> 4 THEN
		RAISE EXCEPTION 'migration 0098: RLS is not enabled on all four note tables.';
	END IF;
	IF (SELECT count(*) FROM pg_policies
		WHERE schemaname = current_schema()
			AND tablename IN ('client_invoice_notes', 'client_invoice_note_lines', 'client_invoice_note_series', 'client_invoice_note_policies')) <> 10 THEN
		RAISE EXCEPTION 'migration 0098: expected ten note policies.';
	END IF;
	IF (SELECT count(*) FROM pg_trigger
		WHERE NOT tgisinternal AND tgname IN ('client_invoice_notes_frozen', 'client_invoice_note_lines_frozen',
			'client_invoice_notes_no_truncate', 'client_invoice_note_lines_no_truncate', 'client_invoices_void_needs_no_notes')) <> 5 THEN
		RAISE EXCEPTION 'migration 0098: expected the five note triggers.';
	END IF;
	IF to_regclass('public.client_invoice_notes_tenant_gstin_note_no_unique') IS NULL
		OR to_regclass('public.client_invoice_note_lines_note_invoice_line_unique') IS NULL
		OR to_regclass('public.client_invoice_note_series_tenant_gstin_kind_fy_unique') IS NULL
		OR to_regclass('public.client_invoice_note_policies_tenant_unique') IS NULL THEN
		RAISE EXCEPTION 'migration 0098: a note unique is missing.';
	END IF;

	BEGIN
		-- ── the fixture: an issued ₹10.00 intra-state invoice of one line
		-- (taxable 1000, CGST 90, SGST 90, total 1180, payable 1200, +20).
		INSERT INTO "client_invoices" ("id","tenant_id","client_id","period_start","period_end","status","supplier_gstin",
				"place_of_supply","supply_type","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise",
				"round_off_paise","payable_paise","gaps","warnings","party","content_hash","created_by")
			VALUES (inv, t, c, '2026-09-01', '2026-09-30', 'draft', g, '29', 'intra', 1000, 90, 90, 0, 180, 1180, 20, 1200,
				'[]'::jsonb, '[]'::jsonb, pty, 'probe', u1);
		INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
				"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise")
			VALUES (il, t, inv, gen_random_uuid(), seg_from, seg_to, 'pick', 'per_pick', NULL, 10, 100, 1000, '996719', 1800, '29', 'intra', 90, 90, 0);
		UPDATE "client_invoices" SET "status" = 'issued', "invoice_no" = '29/S2627/000001', "fy_label" = 'FY-2627', "series_seq" = 1,
				"issued_at" = now(), "issued_by" = u1
			WHERE "id" = inv;

		-- ── accepted: a credit of ₹2.00 — drafted by u1, issued by u2, voided by u3.
		INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","supplier_gstin","place_of_supply","supply_type",
				"reason","reason_note","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
				"party","created_by")
			VALUES (n1, t, c, inv, 'credit', g, '29', 'intra', 'excess-billed', 'probe', 200, 18, 18, 0, 36, 236, 0, 236, pty, u1);
		INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
				"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
			VALUES (gen_random_uuid(), t, n1, il, 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 200, 18, 18, 0);
		UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/000001', "fy_label" = 'FY-2627', "series_seq" = 1,
				"issued_at" = now(), "issued_by" = u2
			WHERE "id" = n1;
		UPDATE "client_invoice_notes" SET "status" = 'void', "void_note" = 'probe', "voided_at" = now(), "voided_by" = u3 WHERE "id" = n1;

		-- ── accepted: a debit of ₹20.00 over the ₹10.00 line, with an override reason, issued by its creator.
		INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","supplier_gstin","place_of_supply","supply_type",
				"reason","reason_note","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
				"party","created_by")
			VALUES (n2, t, c, inv, 'debit', g, '29', 'intra', 'short-billed', 'probe', 2000, 180, 180, 0, 360, 2360, 0, 2360, pty, u1);
		INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
				"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise","override_reason")
			VALUES (gen_random_uuid(), t, n2, il, 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 2000, 180, 180, 0, 'rate agreed after issue');
		UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/D2627/000001', "fy_label" = 'FY-2627', "series_seq" = 1,
				"issued_at" = now(), "issued_by" = u1
			WHERE "id" = n2;

		-- ── accepted: the credit that exhausts the invoice (the void freed n1's cap):
		-- the whole line, exactly its heads, payable = the invoice payable (+20).
		INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","supplier_gstin","place_of_supply","supply_type",
				"reason","reason_note","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
				"party","created_by")
			VALUES (nc, t, c, inv, 'credit', g, '29', 'intra', 'deficiency-in-service', 'probe', 1000, 90, 90, 0, 180, 1180, 20, 1200, pty, u1);
		INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
				"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
			VALUES (gen_random_uuid(), t, nc, il, 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 1000, 90, 90, 0);
		UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/000002', "fy_label" = 'FY-2627', "series_seq" = 2,
				"issued_at" = now(), "issued_by" = u2
			WHERE "id" = nc;

		-- ── accepted: a credit that settles a DISPUTED invoice's dispute, issued by a second person.
		INSERT INTO "client_invoices" ("id","tenant_id","client_id","period_start","period_end","status","supplier_gstin",
				"place_of_supply","supply_type","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise",
				"round_off_paise","payable_paise","gaps","warnings","party","content_hash","created_by")
			VALUES (inv2, t, c, '2026-08-01', '2026-08-31', 'draft', g, '29', 'intra', 1000, 90, 90, 0, 180, 1180, 20, 1200,
				'[]'::jsonb, '[]'::jsonb, pty, 'probe', u1);
		INSERT INTO "client_invoice_lines" ("id","tenant_id","invoice_id","rate_card_id","segment_from","segment_to","charge_code","basis",
				"uom","quantity","unit_amount_paise","amount_paise","sac_code","gst_bps","place_of_supply","supply_type","cgst_paise","sgst_paise","igst_paise")
			VALUES (il2, t, inv2, gen_random_uuid(), '2026-07-31T18:30:00Z', '2026-08-31T18:30:00Z', 'pick', 'per_pick', NULL, 10, 100, 1000, '996719', 1800, '29', 'intra', 90, 90, 0);
		UPDATE "client_invoices" SET "status" = 'issued', "invoice_no" = '29/S2627/000002', "fy_label" = 'FY-2627', "series_seq" = 2,
				"issued_at" = now(), "issued_by" = u1
			WHERE "id" = inv2;
		UPDATE "client_invoices" SET "status" = 'disputed', "status_note" = 'probe', "status_changed_at" = now(), "status_changed_by" = u1 WHERE "id" = inv2;
		INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","supplier_gstin","place_of_supply","supply_type",
				"reason","reason_note","settles_dispute","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
				"party","created_by")
			VALUES (ns, t, c, inv2, 'credit', g, '29', 'intra', 'deficiency-in-service', 'probe', true, 100, 9, 9, 0, 18, 118, 0, 118, pty, u1);
		INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
