				"reason","reason_note","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
				"party","created_by")
			VALUES (nb, t, c, inv, 'credit', g, '29', 'intra', 'post-supply-discount', 'probe', 100, 9, 9, 0, 18, 118, 0, 118, pty, u1);
		INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
				"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
			VALUES (lb, t, nb, il, 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 100, 9, 9, 0);

		INSERT INTO "client_invoice_note_series" ("id","tenant_id","supplier_gstin","kind","fy_label","last_seq")
			VALUES (gen_random_uuid(), t, g, 'credit', 'FY-2627', 2), (gen_random_uuid(), t, g, 'debit', 'FY-2627', 1);
		INSERT INTO "client_invoice_note_policies" ("id","tenant_id","require_second_approver","updated_by")
			VALUES (gen_random_uuid(), t, true, u1);

		-- ── the trigger refusals (P0001), each matched on its message.
		FOREACH probe IN ARRAY ARRAY[
			'issue over the cap',
			'issue by the creator',
			'insert for another client',
			'insert already issued',
			'void to issued',
			'void to draft',
			'edit an issued note',
			'delete an issued note',
			'line on an issued note',
			'line of another invoice',
			'line that does not copy',
			'void a settling credit',
			'invoice void with an issued note',
			'truncate the notes'
		] LOOP
			refused_by := NULL;
			refused_message := NULL;
			expected := CASE probe
				WHEN 'issue over the cap' THEN '%exceeds invoice line%'
				WHEN 'issue by the creator' THEN '%needs a second approver%'
				WHEN 'insert for another client' THEN '%copies its invoice%'
				WHEN 'insert already issued' THEN '%born a draft%'
				WHEN 'void to issued' THEN '%is not a transition%'
				WHEN 'void to draft' THEN '%is not a transition%'
				WHEN 'edit an issued note' THEN '%never changes%'
				WHEN 'delete an issued note' THEN '%never deleted%'
				WHEN 'line on an issued note' THEN '%lines are frozen%'
				WHEN 'line of another invoice' THEN '%is not a line of the note%'
				WHEN 'line that does not copy' THEN '%copies its invoice line%'
				WHEN 'void a settling credit' THEN '%is never voided%'
				WHEN 'invoice void with an issued note' THEN '%void its notes first%'
				ELSE '%never truncated%'
			END;
			BEGIN
				CASE probe
					WHEN 'issue over the cap' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/000003', "fy_label" = 'FY-2627', "series_seq" = 3,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nx;
					WHEN 'issue by the creator' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/000003', "fy_label" = 'FY-2627', "series_seq" = 3,
								"issued_at" = now(), "issued_by" = u1
							WHERE "id" = nx;
					WHEN 'insert for another client' THEN
						INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","supplier_gstin","place_of_supply","supply_type",
								"reason","reason_note","subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
								"party","created_by")
							VALUES (gen_random_uuid(), t, c2, inv, 'credit', g, '29', 'intra', 'excess-billed', 'probe', 1, 0, 0, 0, 0, 1, 0, 1, pty, u1);
					WHEN 'insert already issued' THEN
						INSERT INTO "client_invoice_notes" ("id","tenant_id","client_id","invoice_id","kind","status","supplier_gstin","place_of_supply","supply_type",
								"reason","reason_note","note_no","fy_label","series_seq","issued_at","issued_by",
								"subtotal_paise","cgst_paise","sgst_paise","igst_paise","tax_paise","total_paise","round_off_paise","payable_paise",
								"party","created_by")
							VALUES (gen_random_uuid(), t, c, inv, 'credit', 'issued', g, '29', 'intra', 'excess-billed', 'probe', '29/C2627/000009', 'FY-2627', 9, now(), u2,
								1, 0, 0, 0, 0, 1, 0, 1, pty, u1);
					WHEN 'void to issued' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "void_note" = NULL, "voided_at" = NULL, "voided_by" = NULL WHERE "id" = n1;
					WHEN 'void to draft' THEN
						UPDATE "client_invoice_notes" SET "status" = 'draft' WHERE "id" = n1;
					WHEN 'edit an issued note' THEN
						UPDATE "client_invoice_notes" SET "reason_note" = 'rewritten' WHERE "id" = nc;
					WHEN 'delete an issued note' THEN
						DELETE FROM "client_invoice_notes" WHERE "id" = nc;
					WHEN 'line on an issued note' THEN
						INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
								"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
							VALUES (gen_random_uuid(), t, nc, il, 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 1, 0, 0, 0);
					WHEN 'line of another invoice' THEN
						INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
								"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
							VALUES (gen_random_uuid(), t, nx, gen_random_uuid(), 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 1, 0, 0, 0);
					WHEN 'line that does not copy' THEN
						UPDATE "client_invoice_note_lines" SET "sac_code" = '996729' WHERE "id" = lb;
					WHEN 'void a settling credit' THEN
						UPDATE "client_invoice_notes" SET "status" = 'void', "void_note" = 'probe', "voided_at" = now(), "voided_by" = u3
							WHERE "id" = ns;
					WHEN 'invoice void with an issued note' THEN
						UPDATE "client_invoices" SET "status" = 'void', "status_note" = 'probe', "status_changed_at" = now(), "status_changed_by" = u1
							WHERE "id" = inv;
					WHEN 'truncate the notes' THEN
						TRUNCATE "client_invoice_note_lines";
				END CASE;
			EXCEPTION
				WHEN raise_exception THEN
					GET STACKED DIAGNOSTICS refused_message = MESSAGE_TEXT;
					refused_by := 'P0001';
			END;
			IF refused_by IS NULL OR refused_message NOT LIKE expected THEN
				RAISE EXCEPTION 'migration 0098: trigger probe "%" was not refused as expected (got %).', probe, coalesce(refused_message, 'no refusal');
			END IF;
		END LOOP;

		-- ── the CHECK and unique probes: the two row triggers off (rolled
		-- back with this subtransaction), each refused by its own name.
		ALTER TABLE "client_invoice_notes" DISABLE TRIGGER "client_invoice_notes_frozen";
		ALTER TABLE "client_invoice_note_lines" DISABLE TRIGGER "client_invoice_note_lines_frozen";
		FOREACH probe IN ARRAY ARRAY[
			'unknown kind',
			'unknown status',
			'unknown reason',
			'debit reason on a credit',
			'debit that settles',
			'blank reason note',
			'untrimmed reason note',
			'reason note of 501',
			'malformed supplier gstin',
			'malformed place of supply',
			'unknown supply type',
			'totals that do not add up',
			'heads that do not add up',
			'payable that is not total plus round-off',
			'round-off past 50',
			'round-off on a debit',
			'draft with a number',
			'malformed note number',
			'malformed fy',
			'number in the other series',
			'void without its stamp',
			'blank void note',
			'empty party',
			'note number twice',
			'unknown charge',
			'charge on the wrong basis',
			'uom on a handling line',
			'zero amount',
			'malformed sac',
			'igst on an intra line',
			'unknown line supply type',
			'blank override reason',
			'line twice on a note',
			'negative series seq',
			'unknown series kind',
			'series twice',
			'policy twice'
		] LOOP
			refused_by := NULL;
			expected := CASE probe
				WHEN 'unknown kind' THEN 'client_invoice_notes_kind'
				WHEN 'unknown status' THEN 'client_invoice_notes_status'
				WHEN 'unknown reason' THEN 'client_invoice_notes_reason'
				WHEN 'debit reason on a credit' THEN 'client_invoice_notes_reason'
				WHEN 'debit that settles' THEN 'client_invoice_notes_settles'
				WHEN 'blank reason note' THEN 'client_invoice_notes_reason_note'
				WHEN 'untrimmed reason note' THEN 'client_invoice_notes_reason_note'
				WHEN 'reason note of 501' THEN 'client_invoice_notes_reason_note'
				WHEN 'malformed supplier gstin' THEN 'client_invoice_notes_tax_shape'
				WHEN 'malformed place of supply' THEN 'client_invoice_notes_tax_shape'
				WHEN 'unknown supply type' THEN 'client_invoice_notes_tax_shape'
				WHEN 'totals that do not add up' THEN 'client_invoice_notes_totals'
				WHEN 'heads that do not add up' THEN 'client_invoice_notes_totals'
				WHEN 'payable that is not total plus round-off' THEN 'client_invoice_notes_totals'
				WHEN 'round-off past 50' THEN 'client_invoice_notes_totals'
				WHEN 'round-off on a debit' THEN 'client_invoice_notes_totals'
				WHEN 'draft with a number' THEN 'client_invoice_notes_numbered'
				WHEN 'malformed note number' THEN 'client_invoice_notes_numbered'
				WHEN 'malformed fy' THEN 'client_invoice_notes_numbered'
				WHEN 'number in the other series' THEN 'client_invoice_notes_numbered'
				WHEN 'void without its stamp' THEN 'client_invoice_notes_void'
				WHEN 'blank void note' THEN 'client_invoice_notes_void'
				WHEN 'empty party' THEN 'client_invoice_notes_party'
				WHEN 'note number twice' THEN 'client_invoice_notes_tenant_gstin_note_no_unique'
				WHEN 'unknown charge' THEN 'client_invoice_note_lines_charge_basis'
				WHEN 'charge on the wrong basis' THEN 'client_invoice_note_lines_charge_basis'
				WHEN 'uom on a handling line' THEN 'client_invoice_note_lines_uom_basis'
				WHEN 'zero amount' THEN 'client_invoice_note_lines_amount'
				WHEN 'malformed sac' THEN 'client_invoice_note_lines_tax'
				WHEN 'igst on an intra line' THEN 'client_invoice_note_lines_tax'
				WHEN 'unknown line supply type' THEN 'client_invoice_note_lines_tax'
				WHEN 'blank override reason' THEN 'client_invoice_note_lines_override_reason'
				WHEN 'line twice on a note' THEN 'client_invoice_note_lines_note_invoice_line_unique'
				WHEN 'negative series seq' THEN 'client_invoice_note_series_shape'
				WHEN 'unknown series kind' THEN 'client_invoice_note_series_shape'
				WHEN 'series twice' THEN 'client_invoice_note_series_tenant_gstin_kind_fy_unique'
				ELSE 'client_invoice_note_policies_tenant_unique'
			END;
			BEGIN
				CASE probe
					WHEN 'unknown kind' THEN UPDATE "client_invoice_notes" SET "kind" = 'refund' WHERE "id" = nb;
					WHEN 'unknown status' THEN
						UPDATE "client_invoice_notes" SET "status" = 'pending', "note_no" = '29/C2627/000009', "fy_label" = 'FY-2627', "series_seq" = 9,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nb;
					WHEN 'unknown reason' THEN UPDATE "client_invoice_notes" SET "reason" = 'goodwill' WHERE "id" = nb;
					WHEN 'debit reason on a credit' THEN UPDATE "client_invoice_notes" SET "reason" = 'short-billed' WHERE "id" = nb;
					WHEN 'debit that settles' THEN
						UPDATE "client_invoice_notes" SET "kind" = 'debit', "reason" = 'short-billed', "settles_dispute" = true WHERE "id" = nb;
					WHEN 'blank reason note' THEN UPDATE "client_invoice_notes" SET "reason_note" = '' WHERE "id" = nb;
					WHEN 'untrimmed reason note' THEN UPDATE "client_invoice_notes" SET "reason_note" = ' padded ' WHERE "id" = nb;
					WHEN 'reason note of 501' THEN UPDATE "client_invoice_notes" SET "reason_note" = repeat('x', 501) WHERE "id" = nb;
					WHEN 'malformed supplier gstin' THEN UPDATE "client_invoice_notes" SET "supplier_gstin" = 'GSTIN' WHERE "id" = nb;
					WHEN 'malformed place of supply' THEN UPDATE "client_invoice_notes" SET "place_of_supply" = '2' WHERE "id" = nb;
					WHEN 'unknown supply type' THEN UPDATE "client_invoice_notes" SET "supply_type" = 'export' WHERE "id" = nb;
					WHEN 'totals that do not add up' THEN UPDATE "client_invoice_notes" SET "subtotal_paise" = 101 WHERE "id" = nb;
					WHEN 'heads that do not add up' THEN UPDATE "client_invoice_notes" SET "cgst_paise" = 10 WHERE "id" = nb;
					WHEN 'payable that is not total plus round-off' THEN UPDATE "client_invoice_notes" SET "payable_paise" = 200 WHERE "id" = nb;
					WHEN 'round-off past 50' THEN UPDATE "client_invoice_notes" SET "round_off_paise" = 51, "payable_paise" = 169 WHERE "id" = nb;
					WHEN 'round-off on a debit' THEN
						UPDATE "client_invoice_notes" SET "kind" = 'debit', "reason" = 'short-billed', "round_off_paise" = 2, "payable_paise" = 120 WHERE "id" = nb;
					WHEN 'draft with a number' THEN UPDATE "client_invoice_notes" SET "note_no" = '29/C2627/000009' WHERE "id" = nb;
					WHEN 'malformed note number' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/1', "fy_label" = 'FY-2627', "series_seq" = 9,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nb;
					WHEN 'malformed fy' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/000009', "fy_label" = 'FY-26', "series_seq" = 9,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nb;
					WHEN 'number in the other series' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/D2627/000009', "fy_label" = 'FY-2627', "series_seq" = 9,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nb;
					WHEN 'void without its stamp' THEN
						UPDATE "client_invoice_notes" SET "status" = 'void', "note_no" = '29/C2627/000009', "fy_label" = 'FY-2627', "series_seq" = 9,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nb;
					WHEN 'blank void note' THEN
						UPDATE "client_invoice_notes" SET "status" = 'void', "note_no" = '29/C2627/000009', "fy_label" = 'FY-2627', "series_seq" = 9,
								"issued_at" = now(), "issued_by" = u2, "voided_at" = now(), "voided_by" = u3, "void_note" = ''
							WHERE "id" = nb;
					WHEN 'empty party' THEN UPDATE "client_invoice_notes" SET "party" = '{}'::jsonb WHERE "id" = nb;
					WHEN 'note number twice' THEN
						UPDATE "client_invoice_notes" SET "status" = 'issued', "note_no" = '29/C2627/000001', "fy_label" = 'FY-2627', "series_seq" = 1,
								"issued_at" = now(), "issued_by" = u2
							WHERE "id" = nb;
					WHEN 'unknown charge' THEN UPDATE "client_invoice_note_lines" SET "charge_code" = 'packing' WHERE "id" = lb;
					WHEN 'charge on the wrong basis' THEN UPDATE "client_invoice_note_lines" SET "basis" = 'per_order' WHERE "id" = lb;
					WHEN 'uom on a handling line' THEN UPDATE "client_invoice_note_lines" SET "uom" = 'each' WHERE "id" = lb;
					WHEN 'zero amount' THEN UPDATE "client_invoice_note_lines" SET "amount_paise" = 0 WHERE "id" = lb;
					WHEN 'malformed sac' THEN UPDATE "client_invoice_note_lines" SET "sac_code" = '9967' WHERE "id" = lb;
					WHEN 'igst on an intra line' THEN UPDATE "client_invoice_note_lines" SET "igst_paise" = 1 WHERE "id" = lb;
					WHEN 'unknown line supply type' THEN UPDATE "client_invoice_note_lines" SET "supply_type" = 'export' WHERE "id" = lb;
					WHEN 'blank override reason' THEN UPDATE "client_invoice_note_lines" SET "override_reason" = ' ' WHERE "id" = lb;
					WHEN 'line twice on a note' THEN
						INSERT INTO "client_invoice_note_lines" ("id","tenant_id","note_id","invoice_line_id","charge_code","basis","uom","segment_from","segment_to",
								"sac_code","gst_bps","place_of_supply","supply_type","amount_paise","cgst_paise","sgst_paise","igst_paise")
							VALUES (gen_random_uuid(), t, nb, il, 'pick', 'per_pick', NULL, seg_from, seg_to, '996719', 1800, '29', 'intra', 1, 0, 0, 0);
					WHEN 'negative series seq' THEN
						INSERT INTO "client_invoice_note_series" ("id","tenant_id","supplier_gstin","kind","fy_label","last_seq")
							VALUES (gen_random_uuid(), t, g, 'credit', 'FY-2728', -1);
					WHEN 'unknown series kind' THEN
						INSERT INTO "client_invoice_note_series" ("id","tenant_id","supplier_gstin","kind","fy_label","last_seq")
							VALUES (gen_random_uuid(), t, g, 'refund', 'FY-2728', 0);
					WHEN 'series twice' THEN
						INSERT INTO "client_invoice_note_series" ("id","tenant_id","supplier_gstin","kind","fy_label","last_seq")
							VALUES (gen_random_uuid(), t, g, 'credit', 'FY-2627', 0);
					WHEN 'policy twice' THEN
						INSERT INTO "client_invoice_note_policies" ("id","tenant_id","require_second_approver","updated_by")
							VALUES (gen_random_uuid(), t, false, u1);
				END CASE;
			EXCEPTION
				WHEN check_violation OR unique_violation THEN
					GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			END;
			IF refused_by IS DISTINCT FROM expected THEN
				RAISE EXCEPTION 'migration 0098: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
			END IF;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0098', MESSAGE = 'rollback the 0098 probes';
	EXCEPTION
		WHEN SQLSTATE 'P0098' THEN NULL;
	END;

	IF EXISTS (SELECT 1 FROM "client_invoices" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_invoice_notes" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_invoice_note_lines" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_invoice_note_series" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "client_invoice_note_policies" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0098: a probe row survived.';
	END IF;
	IF (SELECT count(*) FROM pg_trigger
		WHERE tgname IN ('client_invoice_notes_frozen', 'client_invoice_note_lines_frozen') AND tgenabled = 'O') <> 2 THEN
		RAISE EXCEPTION 'migration 0098: the note row triggers are not enabled after the probes.';
	END IF;
END $$;
